    std::vector<Polygon2d> faces;

    for (auto fit = arr.faces_begin(); fit != arr.faces_end(); ++fit) {
        // The unbounded face is not a bounded polygon
        if (arr.is_unbounded(*fit)) {
            continue;
        }

        Polygon2d polygon;

        // Get the inner boundary of the face
        // In CGAL Arrangement_2, the inner boundary of a face is traversed 
        // counter-clockwise.
        auto halfedge = fit->outer_halfedge();
        if (halfedge == nullptr) {
            continue;
        }

        auto start_halfedge = halfedge;
        do {
            // Extract the source vertex of the halfedge
            auto v = arr.source(halfedge);
            polygon.push_back(Point2d(CGAL::to_double(v.x()), CGAL::to_double(v.y())));

            halfedge = halfedge->next();
        } while (halfedge != start_halfedge);

        faces.push_back(polygon);
    }

    return faces;
